// src/pages/Login.js
import React, { useState } from "react";

function Login() {
  // State cho form
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const handleLogin = (e) => {
    e.preventDefault();
    alert(`Đăng nhập với email: ${email} và mật khẩu: ${password}`);
    // TODO: thêm logic đăng nhập thực tế
  };

  const handleRegister = (e) => {
    e.preventDefault();
    alert(`Đăng ký với email: ${email} và mật khẩu: ${password}`);
    // TODO: thêm logic đăng ký thực tế
  };

  return (
    <div className="login-register-page" style={{ padding: "50px 20px", maxWidth: "500px", margin: "0 auto" }}>
      <h1 style={{ textAlign: "center", marginBottom: "30px" }}>Đăng nhập / Đăng ký</h1>

      {/* Form đăng nhập */}
      <form onSubmit={handleLogin} style={{ marginBottom: "40px" }}>
        <h2>Đăng nhập</h2>
        <label>Email *</label>
        <input
          type="email"
          placeholder="Nhập email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
          style={{ width: "100%", padding: "10px", margin: "10px 0" }}
        />
        <label>Mật khẩu *</label>
        <input
          type="password"
          placeholder="Nhập mật khẩu"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          style={{ width: "100%", padding: "10px", margin: "10px 0" }}
        />
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px" }}>
          <label>
            <input type="checkbox" /> Nhớ mật khẩu
          </label>
          <a href="#">Quên mật khẩu?</a>
        </div>
        <button type="submit" style={{ width: "100%", padding: "10px", background: "#333", color: "#fff", border: "none", cursor: "pointer" }}>
          Đăng nhập
        </button>
      </form>

      {/* Form đăng ký */}
      <form onSubmit={handleRegister}>
        <h2>Đăng ký</h2>
        <label>Email *</label>
        <input
          type="email"
          placeholder="Nhập email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
          style={{ width: "100%", padding: "10px", margin: "10px 0" }}
        />
        <label>Mật khẩu *</label>
        <input
          type="password"
          placeholder="Nhập mật khẩu"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          style={{ width: "100%", padding: "10px", margin: "10px 0" }}
        />
        <p style={{ fontSize: "12px", color: "#666", marginBottom: "10px" }}>
          Một mật khẩu sẽ được gửi đến địa chỉ email của bạn.
        </p>
        <button type="submit" style={{ width: "100%", padding: "10px", background: "#555", color: "#fff", border: "none", cursor: "pointer" }}>
          Đăng ký
        </button>
      </form>
    </div>
  );
}

export default Login;
